"""Compare truth (the fake's log and the app outcome) with the exported spans. Pure.

Checks, in order:
  run_status   app raised / got a result -> top-level span ERROR / not ERROR. The top level is
               the trace root (for the Agents SDK, "Agent workflow"); orphans only if no root
               was exported
  call_status  provider error or failed stream -> that LLM span ERROR with an exception event
  call_count   one LLM span per provider request (this check reports extra spans)
  span_closed  every request has an ended, exported span (this check reports missing spans)
  tokens       per-span input/output tokens equal what the provider sent; only where usage was sent
  output       text, refusal and tool calls the app received are on the span; tool args equal as JSON
  finish       finish reason / response status recorded; failed and incomplete visible
  tools        framework runs: every tool that really ran has a tool span; a tool that raised
               has an ERROR span or an exception event
  error_recorded  the app raised and no provider call failed (the error came from the
               framework: unknown tool, max turns, a tool) -> some span is ERROR or has an
               exception event
  request_changed  (note) the library changed the request, e.g. added stream_options.include_usage

Severity: HIGH changes a number or status a dashboard shows by default (run
status, cost, call count); MEDIUM is wrong or missing detail in a span; LOW is
extra or cosmetic.
"""

from __future__ import annotations

import json
from typing import Any

from trueup.core.adapters import ADAPTERS, Adapter, SpanFacts, facts, is_llm_span, norm_finish, tool_span_name
from trueup.core.model import Mismatch, Observation, Severity

HIGH, MEDIUM, LOW = Severity.HIGH, Severity.MEDIUM, Severity.LOW
CHECKS = ("run_status", "call_status", "call_count", "span_closed", "tokens", "output", "finish", "tools",
          "error_recorded", "request_changed")

FAILED_CALL = ("http_error", "error_event", "cut")
# The app got the whole reply for these, so output and finish must be on the span.
COMPLETE_CALL = ("complete", "incomplete")


def _lead(check: str, field: str, truth: Any, trace: Any, severity: Severity) -> Mismatch:
    return Mismatch(field=field, truth=truth, trace=trace, severity=severity, check=check)


def top_level(spans: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Trace roots. A span whose parent was not exported counts only when no root was."""
    roots = [s for s in spans if s.get("parent_id") is None]
    if roots:
        return roots
    ids = {s["span_id"] for s in spans}
    return [s for s in spans if s.get("parent_id") not in ids]


def _errored(span: dict[str, Any]) -> bool:
    return span["status"]["code"] == "ERROR" or any(e.get("name") == "exception" for e in span.get("events", []))


def match_calls(calls: list[dict[str, Any]], llm: list[tuple[dict[str, Any], SpanFacts]]) -> list[int | None]:
    """For each call, the index of its LLM span (or None). Response id first, then start order."""
    out: list[int | None] = [None] * len(calls)
    used: set[int] = set()
    for ci, c in enumerate(calls):
        for si, (_, f) in enumerate(llm):
            if si not in used and c.get("response_id") and f.response_id == c["response_id"]:
                out[ci] = si
                used.add(si)
                break
    free = [si for si in range(len(llm)) if si not in used and llm[si][1].response_id is None]
    for ci in range(len(calls)):
        if out[ci] is None and free:
            out[ci] = free.pop(0)
    return out


def _args_equal(truth: Any, trace: Any) -> bool:
    def parse(v: Any) -> Any:
        if isinstance(v, str):
            try:
                return json.loads(v)
            except ValueError:
                return v
        return v

    return parse(truth) == parse(trace)


def _partial_read(truth: dict[str, Any]) -> bool:
    # The app closed the stream early, so it never received the full reply.
    result = (truth.get("app") or {}).get("result")
    return isinstance(result, dict) and "chunks_read" in result


def compare(obs: Observation, adapter: Adapter | None = None) -> list[Mismatch]:
    truth, trace = obs.truth, obs.trace
    adapter = adapter or ADAPTERS[trace["library"]]
    calls: list[dict[str, Any]] = list(truth.get("fake_log") or [])
    spans: list[dict[str, Any]] = sorted(trace.get("spans") or [], key=lambda s: s.get("start_ns") or 0)
    llm = [(s, facts(adapter, s)) for s in spans if is_llm_span(adapter, s)]
    app_raised = truth.get("outcome") == "exception"
    out: list[Mismatch] = []

    # run_status
    tops = top_level(spans)
    if tops:
        codes = [s["status"]["code"] for s in tops]
        if app_raised and "ERROR" not in codes:
            out.append(_lead("run_status", "top-level span status", f"ERROR (app raised {truth.get('exception')})",
                             "/".join(codes), HIGH))
        failed_reply = any(c.get("outcome") == "failed" for c in calls)
        if not app_raised and "ERROR" in codes and not failed_reply:
            out.append(_lead("run_status", "top-level span status", "not ERROR (app got a result)", "ERROR", HIGH))

    match = match_calls(calls, llm)

    # call_count: extra LLM spans (duplicates). Missing ones are span_closed.
    if len(llm) > len(calls):
        out.append(_lead("call_count", "LLM spans", f"{len(calls)} (provider requests)", len(llm), HIGH))

    tokens_sum_ok = True
    if len(llm) == len(calls) and any(c.get("usage_sent") for c in calls):
        real = sum(c["usage"]["input_tokens"] + c["usage"]["output_tokens"] for c in calls if c.get("usage_sent"))
        seen = sum((f.input_tokens or 0) + (f.output_tokens or 0) for _, f in llm)
        tokens_sum_ok = real == seen

    expected = truth.get("expected") or {}
    expected_tokens = expected.get("tokens")
    partial = _partial_read(truth)

    for ci, call in enumerate(calls):
        where = f"call {ci + 1}"
        outcome = call.get("outcome")
        si = match[ci]

        # request_changed (note): the app did not ask for usage, the request carried include_usage.
        # The scenario says what the app asks for; without that, no expected usage means it did not ask.
        if "include_usage" in expected:
            app_asked = ci < len(expected["include_usage"]) and expected["include_usage"][ci]
        else:
            app_asked = not (isinstance(expected_tokens, list) and ci < len(expected_tokens)
                             and expected_tokens[ci] is None)
        if not app_asked and call.get("include_usage"):
            out.append(Mismatch(field=f"{where} stream_options.include_usage", truth="not set by the app",
                                trace="set in the request the provider got", severity=LOW,
                                check="request_changed", kind="note"))

        if si is None:
            out.append(_lead("span_closed", f"{where} span", f"ended and exported ({outcome})", "no span", HIGH))
            continue
        span, f = llm[si]

        if outcome in FAILED_CALL:
            has_exc = any(e.get("name") == "exception" for e in span.get("events", []))
            if span["status"]["code"] != "ERROR" or not has_exc:
                actual = span["status"]["code"] + ("" if has_exc else ", no exception event")
                out.append(_lead("call_status", f"{where} span status", f"ERROR with exception event ({outcome})",
                                 actual, MEDIUM))

        if call.get("usage_sent") and not partial:
            want = {"input": call["usage"]["input_tokens"], "output": call["usage"]["output_tokens"]}
            got = {"input": f.input_tokens, "output": f.output_tokens}
            if want != got:
                out.append(_lead("tokens", f"{where} tokens", want, got, MEDIUM if tokens_sum_ok else HIGH))

        if outcome in COMPLETE_CALL and not partial:
            recorded = set(f.texts) | set(f.refusals)
            for t in call.get("text") or []:
                if t and t not in recorded:
                    out.append(_lead("output", f"{where} output text", t, sorted(recorded) or None, MEDIUM))
            want_tools = call.get("tool_calls") or []
            got_tools = list(f.tool_calls)
            if len(want_tools) != len(got_tools) or not all(
                w["name"] == g[0] and _args_equal(w["arguments"], g[1]) for w, g in zip(want_tools, got_tools)
            ):
                out.append(_lead("output", f"{where} tool calls",
                                 [[w["name"], w["arguments"]] for w in want_tools] or None,
                                 [[g[0], g[1]] for g in got_tools] or None, MEDIUM))

        if outcome in ("complete", "incomplete", "failed") and not partial and call.get("finish"):
            want_f = {norm_finish(x) for x in call["finish"]}
            got_f = {norm_finish(x) for x in f.finish}
            errored = span["status"]["code"] == "ERROR"
            if outcome == "failed":
                ok = errored or "failed" in got_f
            elif outcome == "incomplete":
                ok = errored or "length" in got_f
            elif want_f == {"stop"} and call.get("tool_calls") and "completed" in call["finish"]:
                # A completed Responses call that asks for tools: "tool_call" says the same thing.
                ok = got_f in ({"stop"}, {"tool_call"})
            else:
                ok = want_f == got_f
            if not ok:
                out.append(_lead("finish", f"{where} finish", sorted(call["finish"]),
                                 sorted(f.finish) or None, MEDIUM))

    out += _tools(truth.get("tool_runs") or [], spans, adapter)

    # error_recorded: an error that did not come from a provider call must still show somewhere.
    if app_raised and spans and not any(c.get("outcome") in FAILED_CALL for c in calls):
        if not any(_errored(s) for s in spans):
            out.append(_lead("error_recorded", "any span", f"ERROR or exception event ({truth.get('exception')})",
                             "no span records an error", MEDIUM))
    return out


def _tools(runs: list[dict[str, Any]], spans: list[dict[str, Any]], adapter: Adapter) -> list[Mismatch]:
    """Pair each real tool run with a tool span of the same name, in start order."""
    if adapter.tool_kind is None:
        return []
    by_name: dict[str, list[dict[str, Any]]] = {}
    for s in spans:
        name = tool_span_name(adapter, s)
        if name is not None:
            by_name.setdefault(name, []).append(s)
    out = []
    for i, run in enumerate(runs):
        where = f"tool run {i + 1} ({run['name']})"
        queue = by_name.get(run["name"]) or []
        if not queue:
            out.append(_lead("tools", f"{where} span", f"tool span ({run['outcome']})", "no span", MEDIUM))
            continue
        span = queue.pop(0)
        if run["outcome"] == "raised" and not _errored(span):
            out.append(_lead("tools", f"{where} status", "ERROR or exception event (tool raised)",
                             span["status"]["code"], MEDIUM))
    extra = sum(len(q) for q in by_name.values())
    if extra:
        out.append(_lead("tools", "tool spans", f"{len(runs)} (tool runs)", len(runs) + extra, LOW))
    return out


def leads(mismatches: list[Mismatch]) -> list[Mismatch]:
    return [m for m in mismatches if m.kind == "lead"]
"""Parent side: run one scenario in a fresh subprocess and read its observation."""

from __future__ import annotations

import json
import os
import subprocess
import tempfile
import time
from pathlib import Path
from typing import Any

from trueup.runner.setups import CHILD_ENV, CHILD_ENV_DROP
from trueup.scenarios import BUILT, get

SRC = Path(__file__).resolve().parents[2]  # .../src
RAN = "ran"
NOT_RUN = "not_run"


def child_env(base: dict[str, str] | None = None) -> dict[str, str]:
    env = dict(os.environ if base is None else base)
    for k in CHILD_ENV_DROP:
        env.pop(k, None)
    env.update(CHILD_ENV)
    env["PYTHONPATH"] = str(SRC)
    env.pop("VIRTUAL_ENV", None)
    return env


def not_run(scenario_id: str, library: str, reason: str, seconds: float = 0.0, detail: str | None = None) -> dict[str, Any]:
    return {"scenario": scenario_id, "library": library, "status": NOT_RUN, "reason": reason,
            "detail": detail, "seconds": round(seconds, 3), "observation": None}


def _last_line(text: str) -> str:
    lines = [ln for ln in text.strip().splitlines() if ln.strip()]
    return lines[-1].strip() if lines else "no output"


def run_scenario(python: Path, library: str, scenario_id: str, timeout: float = 90) -> dict[str, Any]:
    """Returns {scenario, library, status, reason, seconds, observation}."""
    try:
        scenario = get(scenario_id)
    except KeyError as e:
        return not_run(scenario_id, library, str(e))
    if scenario.status != BUILT:
        return not_run(scenario_id, library, f"scenario is {scenario.status}")
    return _run_child(python, library, scenario_id, [library, scenario_id], timeout)


def run_audit(python: Path, library: str, script: Path, label: str, overrides: dict[str, str],
              timeout: float = 90) -> dict[str, Any]:
    """Run a user's script's main() with the fake answering as `overrides` say. Same shape as run_scenario."""
    with tempfile.TemporaryDirectory(prefix="trueup-") as tmp:
        ov = Path(tmp) / "overrides.json"
        ov.write_text(json.dumps(overrides))
        return _run_child(python, library, label, ["--audit", library, str(script.resolve()), str(ov)], timeout)


def _run_child(python: Path, library: str, label: str, args: list[str], timeout: float) -> dict[str, Any]:
    with tempfile.TemporaryDirectory(prefix="trueup-") as tmp:
        out = Path(tmp) / "obs.json"
        cmd = [str(python), "-m", "trueup.runner.child", *args, str(out)]
        t0 = time.monotonic()
        try:
            p = subprocess.run(cmd, env=child_env(), cwd=tmp, capture_output=True, text=True, timeout=timeout)
        except subprocess.TimeoutExpired:
            return not_run(label, library, f"timed out after {timeout:.0f} s", time.monotonic() - t0)
        except OSError as e:
            return not_run(label, library, f"could not start {python}: {e}")
        seconds = time.monotonic() - t0
        if not out.exists():
            tail = (p.stderr or p.stdout).strip()[-2000:]
            return not_run(label, library, f"child exited {p.returncode} without output: {_last_line(tail)}",
                           seconds, detail=tail)
        payload = json.loads(out.read_text())
    if not payload["ok"]:
        return not_run(label, library, "setup or harness error: " + _last_line(payload["error"]), seconds,
                       detail=payload["error"])
    return {"scenario": label, "library": library, "status": RAN, "reason": None,
            "seconds": round(seconds, 3), "observation": payload["observation"]}
"""Per-library venvs under .trueup/venvs/<lib>, built with uv."""

from __future__ import annotations

import json
import shutil
import subprocess
from pathlib import Path

from trueup.runner.setups import PACKAGES

STAMP = "trueup-packages.json"


class VenvError(RuntimeError):
    pass


def venv_dir(root: Path, library: str) -> Path:
    return root.resolve() / ".trueup" / "venvs" / library


def python_path(root: Path, library: str) -> Path:
    return venv_dir(root, library) / "bin" / "python"


def is_ready(root: Path, library: str) -> bool:
    stamp = venv_dir(root, library) / STAMP
    if not stamp.exists() or not python_path(root, library).exists():
        return False
    try:
        return json.loads(stamp.read_text()) == PACKAGES[library]
    except ValueError:
        return False


def ensure(root: Path, library: str, timeout: float = 900) -> Path:
    """Create the venv if missing or out of date. Returns its python."""
    if library not in PACKAGES:
        raise VenvError(f"unknown library {library!r}")
    py = python_path(root, library)
    if is_ready(root, library):
        return py
    uv = shutil.which("uv")
    if uv is None:
        raise VenvError("uv not found on PATH")
    d = venv_dir(root, library)
    d.parent.mkdir(parents=True, exist_ok=True)
    steps = [
        [uv, "venv", "--quiet", "--allow-existing", "--python", "3.12", str(d)],
        [uv, "pip", "install", "--quiet", "--python", str(py), *PACKAGES[library]],
    ]
    for cmd in steps:
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        except subprocess.TimeoutExpired:
            raise VenvError(f"timed out: {' '.join(cmd[:3])}") from None
        if p.returncode != 0:
            raise VenvError(f"{' '.join(cmd[:3])} failed: {(p.stderr or p.stdout).strip()[-500:]}")
    (d / STAMP).write_text(json.dumps(PACKAGES[library]))
    return py
"""Runs one scenario under one library. Executed in a fresh subprocess.

python -m trueup.runner.child <library> <scenario_id> <out.json>
python -m trueup.runner.child --audit <library> <script.py> <overrides.json> <out.json>
"""

from __future__ import annotations

import asyncio
import gc
import importlib.util
import inspect
import json
import os
import logging
import sys
import time
import traceback
from importlib import metadata
from typing import Any

from trueup.fake import FakeProvider
from trueup.runner import truth
from trueup.runner import framework_apps
from trueup.runner.apps import APPS
from trueup.runner.setups import SETUPS, VERSIONED, check_framework, quiet_agents_sdk
from trueup.scenarios import get

ATTR_MAX = 2000


def _value(v: Any) -> Any:
    if isinstance(v, (tuple, list)):
        return [_value(x) for x in v]
    if isinstance(v, str) and len(v) > ATTR_MAX:
        return v[:ATTR_MAX] + f"...[{len(v) - ATTR_MAX} more chars]"
    return v


def span_to_dict(s: Any) -> dict[str, Any]:
    ctx = s.get_span_context()
    return {
        "name": s.name,
        "kind": s.kind.name,
        "trace_id": format(ctx.trace_id, "032x"),
        "span_id": format(ctx.span_id, "016x"),
        "parent_id": format(s.parent.span_id, "016x") if s.parent else None,
        "start_ns": s.start_time,
        "end_ns": s.end_time,
        "status": {"code": s.status.status_code.name, "description": s.status.description},
        "scope": s.instrumentation_scope.name if s.instrumentation_scope else None,
        "attributes": {k: _value(v) for k, v in (s.attributes or {}).items()},
        "events": [{"name": e.name, "attributes": {k: _value(v) for k, v in (e.attributes or {}).items()}} for e in s.events],
    }


def _versions(library: str) -> dict[str, str | None]:
    out: dict[str, str | None] = {}
    for dist in VERSIONED[library]:
        try:
            out[dist] = metadata.version(dist)
        except metadata.PackageNotFoundError:
            out[dist] = None
    return out


def run(library: str, scenario_id: str) -> dict[str, Any]:
    scenario = get(scenario_id)
    logging.disable(logging.CRITICAL)
    exporter, flush = SETUPS[library](scenario.framework)
    check_framework(scenario.framework)
    if scenario.framework == "openai-agents":
        quiet_agents_sdk()
    app_fn = APPS[scenario.app]
    framework_apps.TOOL_RUNS.clear()
    with FakeProvider() as fake:
        t0 = time.monotonic()
        try:
            result = app_fn(fake.base_url, scenario.model)
            app = {"outcome": "ok", "result": result}
        except BaseException as e:  # noqa: BLE001 - the outcome is the data
            app = {
                "outcome": "exception",
                "exception_type": type(e).__name__,
                "exception_module": type(e).__module__,
                "message": str(e)[:500],
            }
        app["seconds"] = round(time.monotonic() - t0, 3)
        # Let streams closed by garbage collection end their spans.
        gc.collect()
        flush()
        fake_log = fake.log.entries()
    spans = [span_to_dict(s) for s in exporter.get_finished_spans()]
    t = truth.derive(fake_log, app, framework_apps.TOOL_RUNS)
    return {
        "truth": {
            **t,
            "scenario": scenario_id,
            "expected": scenario.expected,
            "expected_mismatch": truth.check_expected(scenario.expected, t),
            "app": app,
            "fake_log": fake_log,
        },
        "trace": {"library": library, "versions": _versions(library), "spans": spans},
    }


def _load_main(script: str) -> Any:
    spec = importlib.util.spec_from_file_location("trueup_audit_target", script)
    if spec is None or spec.loader is None:
        raise ImportError(f"cannot load {script}")
    module = importlib.util.module_from_spec(spec)
    sys.path.insert(0, os.path.dirname(os.path.abspath(script)))
    spec.loader.exec_module(module)
    fn = getattr(module, "main", None)
    if not callable(fn):
        raise AttributeError(f"{script} has no main()")
    return fn


def run_audit(library: str, script: str, overrides: dict[str, str]) -> dict[str, Any]:
    """Run a user's main() with the SDKs pointed at the fake through env base URLs."""
    logging.disable(logging.CRITICAL)
    exporter, flush = SETUPS[library]()
    with FakeProvider(overrides) as fake:
        os.environ["OPENAI_BASE_URL"] = fake.openai_base_url
        os.environ["ANTHROPIC_BASE_URL"] = fake.base_url
        main_fn = _load_main(script)
        t0 = time.monotonic()
        try:
            result = main_fn()
            if inspect.iscoroutine(result):
                result = asyncio.run(result)
            app = {"outcome": "ok", "result": repr(result)[:500]}
        except BaseException as e:  # noqa: BLE001 - the outcome is the data
            app = {
                "outcome": "exception",
                "exception_type": type(e).__name__,
                "exception_module": type(e).__module__,
                "message": str(e)[:500],
            }
        app["seconds"] = round(time.monotonic() - t0, 3)
        gc.collect()
        flush()
        fake_log = fake.log.entries()
    spans = [span_to_dict(s) for s in exporter.get_finished_spans()]
    return {
        "truth": {**truth.derive(fake_log, app), "overrides": overrides, "app": app, "fake_log": fake_log},
        "trace": {"library": library, "versions": _versions(library), "spans": spans},
    }


def main(argv: list[str]) -> int:
    if argv[0] == "--audit":
        library, script, overrides_path, out_path = argv[1:]
        with open(overrides_path) as f:
            overrides = json.load(f)
        job = lambda: run_audit(library, script, overrides)  # noqa: E731
    else:
        library, scenario_id, out_path = argv
        job = lambda: run(library, scenario_id)  # noqa: E731
    try:
        payload = {"ok": True, "observation": job()}
    except BaseException:  # noqa: BLE001 - reported as NOT RUN by the parent
        payload = {"ok": False, "error": traceback.format_exc(limit=8)}
    with open(out_path, "w") as f:
        json.dump(payload, f, default=str)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"""Turn the fake's log and the app outcome into truth fields. Pure functions."""

from __future__ import annotations

from typing import Any


def derive(fake_log: list[dict[str, Any]], app: dict[str, Any],
           tool_runs: list[dict[str, str]] | None = None) -> dict[str, Any]:
    """Truth in the same shape as a scenario's `expected`."""
    out: dict[str, Any] = {
        "calls": len(fake_log),
        "outcome": app["outcome"],
        "tokens": [
            None if e["usage"] is None else {"input": e["usage"]["input_tokens"], "output": e["usage"]["output_tokens"]}
            for e in fake_log
        ],
        "finish": [e["finish"] for e in fake_log],
        "tool_calls": [[t["name"] for t in e["tool_calls"]] for e in fake_log],
        "fake": [e["outcome"] for e in fake_log],
        "response_ids": [e["response_id"] for e in fake_log],
        "include_usage": [e["include_usage"] for e in fake_log],
        "tool_runs": [dict(t) for t in tool_runs or []],
    }
    if app["outcome"] == "exception":
        out["exception"] = app["exception_type"]
    return out


def check_expected(expected: dict[str, Any], truth: dict[str, Any]) -> list[str]:
    """Keys where the run's truth differs from what the scenario expects."""
    return [k for k, v in expected.items() if truth.get(k) != v]

